"""Register exact532 compatibility and three detailed QA cases; never alter user results."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];E=ROOT/'evidence/s1-20261018/sesenta-tandas-473-532'
def main():
    manifest=json.loads((E/'CANDIDATA532-FINAL03.json').read_text());pair={'bundle':manifest['distributions']['frontend']['app.js'],'dll':manifest['distributions']['server']['RackClick.Server.dll']}
    path=ROOT/'docs/QA-CASOS-WASCAR.json';c=json.loads(path.read_text(encoding='utf-8'));previous=c['cases'][:65]
    intro='Sólo si indica DISPONIBLE EN TU SNAPSHOT. Ejecuta INICIAR-QA-RESTAURADO.cmd, usa su ACCESO-PRIVADO.txt y guía restaurada, selecciona Español y pulsa Ctrl+F5. No mezcles cuentas con QA original. Si el caso no está disponible, marca Bloqueado.'
    close='En Tu resultado elige Pass, Not Pass o Bloqueado. Anota nombres ficticios y el paso/mensaje si falla, sin contraseñas, cookies ni tokens. Arriba pulsa Guardar copia de mis resultados; tus notas anteriores se conservan.'
    cases=[
      {'id':'QA-66','module':'Plantillas privadas · diseño','title':'Crear una configuración nueva con grupos independientes','feature':'privateConfigurationGui','steps':[intro,'Entra como Administrador o Técnico con edición del cliente compartido. Abre la tarjeta del cliente ficticio y, en la barra superior del inventario, pulsa Mis plantillas privadas. Dentro del cuadro pulsa Crear configuración nueva.','En Nueva configuración privada, arriba del editor, abre Comenzar desde, elige Configuración vacía y pulsa Usar como borrador. En Nombre de la plantilla nueva escribe QA66 diseño más fecha. El borrador todavía no está guardado.','Elige Equipo de rack en Tipo de objeto y una altura válida. Configura Aspecto del equipo, Icono, Color y Presupuesto PoE si deseas probarlos. Para Toma de pared o Dispositivo final no debe exigirse altura de rack.','En el bloque de grupos pulsa Añadir grupo. Selecciona RJ45, escribe un nombre y prefijo, y elige dos puertos. Añade otro grupo RJ45 con otro nombre/prefijo y un puerto. Aunque ambos contengan el número1, deben seguir siendo dos grupos independientes. No uses sólo el número para identificarlos.','Dentro de cada grupo revisa las filas de puertos. Cambia una etiqueta a QA66 Puerto Ω, una cara y PoE; cambia números sólo de modo que no se repitan dentro del mismo grupo. Un grupo eléctrico debe ofrecer roles apropiados y no PoE. Si cambias familia o reduces cantidad, lee y confirma las consecuencias del cuadro; sólo afecta al borrador.','Debajo pulsa Revisar configuración. Compara grupos, prefijos, números y atributos del preview. En ventana estrecha usa el scroll horizontal dentro de la tabla para ver sus últimas columnas; las letras no deben comprimirse una a una. Marca la casilla de confirmación de etiquetas reutilizables y pulsa Guardar plantilla nueva una sola vez.','Espera El servidor confirmó la plantilla nueva. Cierra el cuadro y vuelve a Mis plantillas privadas; selecciona QA66 para revisar la definición. Pulsa Ctrl+R, vuelve al mismo cliente y repite la consulta: grupos y atributos confirmados permanecen.',close],'expected':'Se guarda otra plantilla propia con confirmación del servidor. Los dos grupos RJ45 conservan identidades separadas y sus números/atributos. Recarga y consulta muestran lo persistido. Un rechazo conserva el borrador o deja intención pendiente para consulta; no anuncia guardado.'},
      {'id':'QA-67','module':'Plantillas privadas · reutilización','title':'Editar como copia y crear un equipo sin cambiar el original','feature':'privateConfigurationGui','steps':[intro,'Prepara una plantilla ficticia con QA-66 o QA-55. En Mis plantillas privadas selecciónala y anota su nombre y configuración, sin borrar ni retirar plantillas anteriores.','Pulsa Crear configuración nueva. En Comenzar desde elige Mi plantilla activa correspondiente por nombre e ID y pulsa Usar como borrador. Cambia Nombre de la plantilla nueva a QA67 copia más fecha, y modifica una etiqueta o prefijo. También puedes probar una semilla del Catálogo BASE: sus modelos no deben modificarse.','Pulsa Revisar configuración, comprueba el preview, marca la confirmación y Guardar plantilla nueva. Espera la confirmación del servidor. En la lista deben existir la plantilla original y la copia; vuelve a consultar la original y verifica que conserva sus datos.','Cierra Mis plantillas privadas. En la barra del inventario pulsa Añadir equipo y selecciona el modo de plantilla privada. En el selector de plantilla elige QA67 copia; revisa el preview, escribe un nombre de equipo ficticio nuevo y elige su rack o sala según el tipo. Guarda y espera Guardado por el servidor.','Consulta los grupos y puertos del equipo nuevo. Deben proceder de la copia, con puertos libres y sin cables heredados. Las tomas/finales se ubican en sala, sin U ni circuitos internos inventados. Los equipos anteriores no deben cambiar por crear otra plantilla.','Pulsa Ctrl+R. Abre otro navegador o perfil separado e inicia sesión con la MISMA cuenta para consultar su biblioteca: debe ver ambas plantillas. Una cuenta técnica distinta puede ver el equipo del cliente si tiene permisos, pero no hereda tu biblioteca privada; la compartición/publicación sigue pendiente.',close],'expected':'La copia y su equipo tienen identidades nuevas; la plantilla original y sus equipos conservan sus atributos. Misma cuenta en otra sesión ve la biblioteca persistida; otro usuario no obtiene plantillas privadas ajenas. Crear un equipo requiere autorización actual de servidor.'},
      {'id':'QA-68','module':'Plantillas privadas · borradores y acceso','title':'Comprobar cierre, idiomas y recuperación sin envíos duplicados','feature':'privateConfigurationGui','steps':[intro,'En Mis plantillas privadas pulsa Crear configuración nueva, elige una semilla con Usar como borrador y escribe QA68 sin guardar en Nombre de la plantilla nueva. Cierra el cuadro: debe pedir confirmación para descartar el borrador. Cancela el cierre y comprueba que conserva lo escrito; después ciérralo confirmando descarte. No debe aparecer una plantilla QA68 guardada.','Si de forma natural un envío queda pendiente o sin confirmación, vuelve a abrir Mis plantillas privadas y busca su aviso de creación pendiente. Pulsa Consultar estado antes de crear otra solicitud. Si confirma guardado, debe aparecer una sola plantilla. No provoques fallos de red ni uses herramientas de desarrollador para esta prueba; anota No realizado si no apareció este caso.','Si recargaste con un envío pendiente, el aviso explica que el hardware del borrador ya no está en memoria y Reintentar queda deshabilitado. Puedes Consultar o Cancelar. NoRecorded no es guardado ni cancelación: conserva pendiente hasta resultado terminal. Sólo después de confirmación podrás reconstruir un borrador nuevo. La variante de pérdida de respuesta ya tiene prueba técnica aislada.','En otra sesión separada entra como Lector, abre el mismo cliente y Mis plantillas privadas. No debe ofrecer el editor Crear configuración nueva ni escritura. No retires permisos de cuentas existentes; esa revocación se prueba técnicamente en otra base.','Con la cuenta editora, vuelve a Todos los clientes en la barra izquierda. En la esquina superior derecha cambia el idioma a English, después Deutsch y Español; abre el editor por cada idioma y comprueba su título y controles. Los nombres escritos por ti no se traducen.','Estrecha la ventana y recorre campos/botones con Tab. Revisar configuración y Guardar plantilla nueva deben ser accesibles; la tabla de preview puede desplazarse horizontalmente dentro de su marco, sin desbordar la página. Durante borrador o solicitud pendiente no se debe aplicar una actualización remota ni completar Click-Click inadvertidamente.',close],'expected':'Cerrar sin guardar pide descartar y no crea una plantilla. La recuperación distingue petición pendiente, guardada, cancelada o no registrada y evita duplicar envíos. El lector no obtiene edición; textos EN/DE/ES y preview legible con scroll. Variantes no realizadas quedan anotadas sin asignar Pass técnico a Wascar.'}
    ]
    c['revision']='2026-10-18-grupo473-532';c['cases']=previous+cases
    inherited=[]
    # Same schema/source contracts and compiled modules; positive compatibility
    # was established by focused legacy/API/GUI/Windows tests, not by case count.
    for key,items in c.items():
        if key.endswith('Builds') and isinstance(items,list) and items and all(isinstance(x,dict) and set(x)=={'bundle','dll'} for x in items):
            if pair not in items:items.append(pair)
            inherited.append(key)
    c['privateConfigurationBuilds']=[pair];assert c['cases'][:65]==previous
    path.write_bytes((json.dumps(c,ensure_ascii=False,indent=2)+'\n').replace('\n','\r\n').encode('utf-8'))
    guide=ROOT/'tools/windows/qa_guide.py';s=guide.read_bytes();anchor=b"        'inventoryChangeDetailsGui': catalog.get('inventoryChangeDetailsBuilds', []),"
    if b"'privateConfigurationGui':" not in s:assert anchor in s;s=s.replace(anchor,anchor+b"\r\n        'privateConfigurationGui': catalog.get('privateConfigurationBuilds', []),");guide.write_bytes(s)
    test=ROOT/'tools/tests/test_qa_guide.py';s=test.read_bytes();old=b"'QA-63','QA-64','QA-65'))";new=b"'QA-63','QA-64','QA-65','QA-66','QA-67','QA-68'))"
    if old in s:assert s.count(old)==2;s=s.replace(old,new);test.write_bytes(s)
    else:assert s.count(new)==2
    (E/'QA-MATRIX-532.json').write_text(json.dumps({'pair':pair,'inheritedBuildLists':inherited,'previous65CasesUnchanged':True,'caseCount':68,'availabilityRequiresSelectedSnapshot':True,'manualWascarResultsWritten':False},indent=2)+'\n',encoding='utf-8')
    print(json.dumps({'cases':68,'compatibleFeatureLists':len(inherited),'previous65Unchanged':True}))
if __name__=='__main__':main()
